Ltac ro_tbl_case MI n lef :=
  match goal with |- ov_read_bytes _ ?m (Z_to_bv 64 ?a) n = Some (lef (Z_to_bv 64 ?v)) =>
    let az := eval vm_compute in a in let vz := eval vm_compute in v in
    replace (Z_to_bv 64 a) with (Z_to_bv 64 az) by (apply bv_eq; vm_compute; reflexivity);
    replace v with vz by (vm_compute; reflexivity);
    let obs := eval vm_compute in (image_bytes asegs az n) in
    lazymatch obs with Some ?bs =>
      let RO := fresh "RO" in
      assert (RO : ro_cells asegs m az [CB n bs]) by (apply (ro_cells_image asegs m az bs MI); [vm_compute; reflexivity | lia | cbn; lia]);
      rewrite (ro_cells_read_at asegs m az [CB n bs] 0%nat (CB n bs) n (Z_to_bv 64 az) RO) by (first [reflexivity | cbn; reflexivity | unfold wa; f_equal; lia]);
      f_equal; apply byte_list_eq; vm_compute; reflexivity
    end
  end.

